/*
  BOOTSTRAPPED by docs/data/generate_app_seed.py from
  docs/data/seed_from_tools_list.json — and then edited by hand ever since.

  The old header said "do not edit by hand", which stopped being true with
  STI-303 and STI-306 and is now actively dangerous: the generator does not
  emit the terminated employee, the reporting chain, `isActive`, or any of the
  role accounts below, so RE-RUNNING IT SILENTLY DELETES SHIPPED SEED WORK and
  takes the HR clearance queue, departure reassignment and every permission
  test down with it.

  Treat this file as the source. The generator is the one-time import of
  Urban's tools list, kept for provenance. If the tools list is reloaded,
  regenerate into a scratch file and merge — never overwrite.
*/

export type ProjectSeed = { key: string; extId: string | null; name: string; description?: string; status: string; start: string; end: string; site: string | null };
export type EmployeeSeed = { key: string; extId: string; name: string; role: string; primary: string | null; status: string; email: string | null; phone: string | null; reportsTo: string | null };
export type PostingSeed = { emp: string; proj: string; from: string; to: string | null; note: string };
export type TeamSeed = { emp: string; proj: string; role: string; from: string; note: string };
export type LocSeed = { key: string; type: string; name: string; warehouse: string | null; project: string | null; custodian: string | null };
export type VehLocSeed = { key: string; type: string; name: string; project: string | null; custodian: string | null };
export type VehSeed = { key: string; loc: string; vtype: 'truck' | 'trailer'; unit: string; plate: string | null; make: string | null; own: string; payee: string | null; allow: string | null; freq: string | null; proj: string | null; foreman: string | null; lat: string | null; lng: string | null; code?: string | null; description?: string | null };
export type AssetSeed = { tag: string | null; make: string | null; modelNumber: string | null; description: string | null; serial: string | null; isSerialized: boolean; quantity: number; cost: string | null; own: string | null; dept: boolean; status: string; cust: string | null; cur: string | null; loc: string };
export type AssignSeed = { tag: string; cust: string; proj: string | null; loc: string; type: string; start: string; end: string | null };
export type TxSeed = { tag: string; event: string; at: string; note: string; ref: string };
export type DeptSeed = { name: string; code: string };
export type UserSeed = {
  email: string;
  first: string;
  last: string;
  role: string;
  employeeKey: string | null;
  isActive?: boolean;
  /* True only for the one seeded account that exercises the invite flow
     (STI-3xx auth work) — see the comment on `userSpecs` below. Distinct from
     plain `isActive: false`: a deactivated account has a real, usable
     password on purpose (STI-303), a pending invite deliberately does not. */
  pendingInvite?: boolean;
};

/*
  STI-104: the register's categories.

  The tools list carries no category column, so every imported asset has
  `category_name` NULL and `category` was seeded EMPTY. That made the whole
  category surface dead from a clean database — `category.list` returned
  nothing, so the bulk re-file picker and the register's category filter both
  offered zero options and could not be exercised without hand-inserting rows
  in psql. CLAUDE.md rule 8: data the seed cannot produce is behaviour nobody
  tests.

  These are the shelves Urban's list actually falls into, read off the tool
  descriptions (drills, grinders, quikie saws, compactors, generators,
  blowers, survey kit). Deliberately a short flat list, not a taxonomy: a
  category is a shelf label, and a hierarchy nobody asked for is a migration
  waiting to happen.
*/
export const categorySpecs: string[] = [
  "Drills & Drivers",
  "Grinders",
  "Saws",
  "Compaction",
  "Generators & Power",
  "Blowers & Yard",
  "Survey & Layout",
  "Hand Tools",
];

