/* ONE account, and it is a real one.

   This replaced the fifteen demo logins that all shared the password
   `stinventory-demo` — including an owner holding every permission. That set is
   correct for a demo and indefensible on a customer-facing deployment, and
   `seed.ts` refuses NODE_ENV=production precisely because of it.

   No password lives here. seed.ts reads SEED_OWNER_PASSWORD, and generates a
   random one it prints ONCE if that is unset — so a credential is never
   committed and never defaults to something guessable.

   employeeKey is null on purpose: the IT owner administers the system, they are
   not a foreman holding tools. */
export const userSpecs: UserSeed[] = [
  { email: "optix_it@optixtec.com", first: "Optix", last: "IT", role: "owner", employeeKey: null },
];
